steps.script:
# The squad a 65 px row at y 600; its attached Blade Champion 112 px (2.8")
# in front of the middle model; the target a 140 px row 8" beyond the leader,
# off to the east. Everyone else parked.
var st = GameState.state
var v = CharacterAttachmentManager.can_attach("U_BLADE_CHAMPION_A", "U_CUSTODIAN_GUARD_B")
if not bool(v.get("valid", false)):
	return "cannot attach: %s" % str(v.get("reason", ""))
CharacterAttachmentManager.attach_character("U_BLADE_CHAMPION_A", "U_CUSTODIAN_GUARD_B")
var g = st.units.U_CUSTODIAN_GUARD_B
var k = 0
for m in g.models:
	m.position = {"x": 900.0 + float(k) * 65.0, "y": 600.0}
	k += 1
for m in st.units.U_BLADE_CHAMPION_A.models:
	m.position = {"x": 1030.0, "y": 712.0}
for uid in ["U_CUSTODIAN_GUARD_B", "U_BLADE_CHAMPION_A"]:
	if st.units[uid].has("flags"):
		st.units[uid].flags.erase("last_shot_idx")
		st.units[uid].flags.erase("shot_recently")
var t = st.units.U_CUSTODIAN_GUARD_C_P2
var j = 0
for m in t.models:
	m.position = {"x": 1150.0 + float(j) * 140.0, "y": 1095.0}
	j += 1
for uid in st.units:
	if uid in ["U_CUSTODIAN_GUARD_B", "U_BLADE_CHAMPION_A", "U_CUSTODIAN_GUARD_C_P2"]:
		continue
	var u = st.units[uid]
	var q = 0
	for m in u.get("models", []):
		if m.get("position") == null:
			continue
		if int(u.get("owner", 0)) == 1:
			m.position = {"x": 600.0 + 40.0 * float(q % 5), "y": 300.0}
		else:
			m.position = {"x": 1500.0 + 40.0 * float(q % 6), "y": 2300.0 - 40.0 * float(q / 6)}
		q += 1
return str(st.units.U_BLADE_CHAMPION_A.get("attached_to", "")) == "U_CUSTODIAN_GUARD_B" and "U_BLADE_CHAMPION_A" in st.units.U_CUSTODIAN_GUARD_B.attachment_data.attached_characters

# FIX_MOVE_FOR_CHARGE ships OFF: load the opt-in profile AFTER configure()
# (configure wipes profiles).
var f = FileAccess.open("res://tests/bench_profiles/move_for_charge_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
return prof.parameters.size()

var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
# The suggested move applied as MovementPhase applies it: every bodyguard model
# to its destination, the attached Blade Champion by the bodyguard's delta.
var dests = d.get("_ai_model_destinations", {})
var board = GameState.create_snapshot()
var delta = null
for m in board.units.U_CUSTODIAN_GUARD_B.models:
	if dests.has(m.id):
		var p = m.position
		var pv = Vector2(float(p.x), float(p.y)) if p is Dictionary else Vector2(p)
		var to = Vector2(float(dests[m.id][0]), float(dests[m.id][1]))
		if delta == null:
			delta = to - pv
		m.position = to
if delta == null:
	return "no destinations"
for m in board.units.U_BLADE_CHAMPION_A.models:
	var p = m.position
	m.position = (Vector2(float(p.x), float(p.y)) if p is Dictionary else Vector2(p)) + delta
# The roll the AI really needs from `board`: the engine must offer the target
# after the roll (11.04, measured from the whole Attached unit) AND the AI's own
# charge move (_compute_charge_move: the bodyguard's models only) must complete.
var exec_first = -1
for r in range(2, 13):
	if str(AIDecisionMaker._compute_charge_move(board, "U_CUSTODIAN_GUARD_B", r, ["U_CUSTODIAN_GUARD_C_P2"], 1).get("type", "")) == "APPLY_CHARGE_MOVE":
		exec_first = r
		break
var tmpl = MoveTypes.get_type("charge")
var sel_first = -1
for r in range(2, 13):
	if "U_CUSTODIAN_GUARD_C_P2" in tmpl._targets_within("U_CUSTODIAN_GUARD_B", board, ChargeMove11e.selectable_distance_ceiling(float(r))):
		sel_first = r
		break
var real = max(sel_first, exec_first)
var desc = str(d.get("_ai_description", ""))
var re_k = RegEx.new()
re_k.compile("staged for a (\\d+)\\+ charge")
var mk = re_k.search(desc)
var claim = int(mk.get_string(1)) if mk != null else -1
return claim == 4 and real == claim and exec_first > sel_first

AIDecisionMaker.clear_player_profile(1)
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var notes = ""
for n in d.get("_ai_move_adjustments", []):
	notes += str(n) + " | "
var desc = str(d.get("_ai_description", ""))
return desc.contains("moves to attack Custodian Guard Gamma") and not desc.contains("staged for a") and not notes.contains("this turn's charge needs a")

# Reload the opt-in profile, execute the suggested move through AIPlayer, then
# measure on the engine's own state (the leader moved by the engine).
var f = FileAccess.open("res://tests/bench_profiles/move_for_charge_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
NetworkIntegration.route_action({"type": "BEGIN_NORMAL_MOVE", "actor_unit_id": "U_CUSTODIAN_GUARD_B", "player": 1})
var ph = PhaseManager.current_phase_instance
if ph.has_method("has_pending_stratagem_window") and ph.has_pending_stratagem_window():
	var w = ph.get_pending_stratagem_window()
	NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": str(w.get("window_id", ""))})
AIPlayer._execute_ai_movement(1, d)
var u = GameState.state.units.U_CUSTODIAN_GUARD_B
var board = GameState.create_snapshot()
# The roll the AI really needs from `board`: the engine must offer the target
# after the roll (11.04, measured from the whole Attached unit) AND the AI's own
# charge move (_compute_charge_move: the bodyguard's models only) must complete.
var exec_first = -1
for r in range(2, 13):
	if str(AIDecisionMaker._compute_charge_move(board, "U_CUSTODIAN_GUARD_B", r, ["U_CUSTODIAN_GUARD_C_P2"], 1).get("type", "")) == "APPLY_CHARGE_MOVE":
		exec_first = r
		break
var tmpl = MoveTypes.get_type("charge")
var sel_first = -1
for r in range(2, 13):
	if "U_CUSTODIAN_GUARD_C_P2" in tmpl._targets_within("U_CUSTODIAN_GUARD_B", board, ChargeMove11e.selectable_distance_ceiling(float(r))):
		sel_first = r
		break
var real = max(sel_first, exec_first)
var desc = str(d.get("_ai_description", ""))
var re_k = RegEx.new()
re_k.compile("staged for a (\\d+)\\+ charge")
var mk = re_k.search(desc)
var claim = int(mk.get_string(1)) if mk != null else -1
var lp = GameState.state.units.U_BLADE_CHAMPION_A.models[0].position
var lv = Vector2(float(lp.x), float(lp.y)) if lp is Dictionary else Vector2(lp)
return bool(u.get("flags", {}).get("moved", false)) and not bool(u.get("flags", {}).get("advanced", false)) and lv.distance_to(Vector2(1030.0, 712.0)) > 40.0 and claim == 4 and real == claim
